                            <p class="card-text">View and manage all shipments, update statuses, and create new shipments.</p>
                            <a href="/shipments" class="btn btn-primary">Go to Shipments</a>
                        </div>
                    </div>
                </div>
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">🔍 Track a Shipment</h5>
                            <p class="card-text">Check your shipment status and estimated delivery date.</p>
                            <a href="/track" class="btn btn-outline-primary">Track Shipment</a>
                        </div>
                    </div>
                </div>
            </div>
