+@page "/shipments"
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+@inject IShipmentService ShipmentService
+@attribute [Microsoft.AspNetCore.Authorization.Authorize]
+
+<PageTitle>Shipments - Dispatcher Dashboard</PageTitle>
+
+<h1>Shipment Management</h1>
+
+<div class="mb-3 d-flex gap-2">
+    <input type="text" class="form-control" placeholder="Filter by destination..."
+           @bind="filterText" @bind:event="oninput" />
+    <select class="form-select w-auto" @bind="statusFilter">
+        <option value="">All Statuses</option>
+        @foreach (var status in Enum.GetValues<ShipmentStatus>())
+        {
+            <option value="@status">@status</option>
+        }
+    </select>
+    <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
+</div>
+
+@if (showCreateForm)
+{
+    <div class="card mb-3">
+        <div class="card-body">
+            <h5>Create New Shipment</h5>
+            <div class="row g-2">
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" type="date" @bind="estimatedDelivery" />
+                </div>
+                <div class="col-md-3">
+                    <button class="btn btn-primary" @onclick="CreateShipment">Create</button>
+                    <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
+                </div>
+            </div>
+            @if (!string.IsNullOrEmpty(createError))
+            {
+                <div class="text-danger mt-2">@createError</div>
+            }
+        </div>
+    </div>
+}
+
+@if (shipments == null)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else if (!FilteredShipments.Any())
+{
+    <p>No shipments found.</p>
+}
+else
+{
+    <table class="table table-striped table-hover">
+        <thead>
+            <tr>
+                <th>Tracking #</th>
+                <th>Origin</th>
+                <th>Destination</th>
+                <th>Status</th>
+                <th>Customer</th>
+                <th>Est. Delivery</th>
+                <th>Actions</th>
+            </tr>
+        </thead>
+        <tbody>
+            @foreach (var shipment in FilteredShipments)
+            {
+                <tr>
+                    <td><code>@shipment.TrackingNumber</code></td>
+                    <td>@shipment.Origin</td>
+                    <td>@shipment.Destination</td>
+                    <td><span class="badge @GetStatusBadge(shipment.Status)">@shipment.Status</span></td>
+                    <td>@shipment.CustomerEmail</td>
+                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
+                    <td>
+                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
+                                value="@shipment.Status"
+                                @onchange="(e) => UpdateStatus(shipment.Id, e)">
+                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                            {
+                                <option value="@status">@status</option>
+                            }
+                        </select>
+                    </td>
+                </tr>
+            }
+        </tbody>
+    </table>
+}
+
+@code {
+    private List<Shipment>? shipments;
+    private string filterText = "";
+    private string statusFilter = "";
+    private bool showCreateForm;
+    private Shipment newShipment = new();
+    private DateTime? estimatedDelivery;
+    private string? createError;
+
+    private IEnumerable<Shipment> FilteredShipments =>
+        (shipments ?? []).Where(s =>
+            (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
+            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter));
+
+    protected override async Task OnInitializedAsync()
+    {
+        shipments = await ShipmentService.GetAllShipmentsAsync();
+    }
+
+    private void ShowCreateForm()
+    {
+        showCreateForm = true;
+        newShipment = new Shipment();
+        estimatedDelivery = null;
+        createError = null;
+    }
+
+    private async Task CreateShipment()
+    {
+        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))
+        {
+            createError = "Origin and Destination are required.";
+            return;
+        }
+
+        newShipment.TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000, 9999)}";
+        newShipment.EstimatedDelivery = estimatedDelivery;
+        newShipment.Status = ShipmentStatus.Pending;
+
+        await ShipmentService.CreateShipmentAsync(newShipment);
+        shipments = await ShipmentService.GetAllShipmentsAsync();
+        showCreateForm = false;
+    }
+
+    private async Task UpdateStatus(int id, ChangeEventArgs e)
+    {
+        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
+        {
+            await ShipmentService.UpdateShipmentStatusAsync(id, status);
+            shipments = await ShipmentService.GetAllShipmentsAsync();
+        }
+    }
+
+    private static string GetStatusBadge(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Delayed => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

