        isLoading = true;
        errorMessage = null;
        trackedShipment = null;
        customerShipments = null;

        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        if (trackedShipment is null)
            errorMessage = $"No shipment found with tracking number '{trackingNumber}'.";

        isLoading = false;
    }

    private async Task SearchByEmail()
    {
        if (string.IsNullOrWhiteSpace(customerEmail)) return;

        isLoading = true;
        errorMessage = null;
        trackedShipment = null;
        customerShipments = null;

        customerShipments = await ShipmentService.GetShipmentsByCustomerAsync(customerEmail.Trim());
        if (!customerShipments.Any())
            errorMessage = $"No shipments found for '{customerEmail}'.";

        isLoading = false;
    }

    private void ViewShipment(Shipment shipment)
    {
        trackedShipment = shipment;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            if (!string.IsNullOrWhiteSpace(trackingNumber))
                await SearchByTracking();
            else if (!string.IsNullOrWhiteSpace(customerEmail))
                await SearchByEmail();
        }
    }

    private static int GetProgress(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        _ => 0
    };

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => ""
    };
}
```

